import json
import os
import re
import time
from pathlib import Path
from typing import Any, Optional, Protocol, Union

import requests

from .apis import mijiaAPI
from .errors import (
    DeviceActionError,
    DeviceGetError,
    DeviceNotFoundError,
    DeviceSetError,
    GetDeviceInfoError,
    MultipleDevicesFoundError,
)
from .logger import logger
from .version import version


device_url = "https://home.miot-spec.com/spec/"


class DeviceInfoCacheBackend(Protocol):
    def get(self, device_model: str) -> Optional[dict[str, Any]]:
        ...

    def set(self, device_model: str, device_info: dict[str, Any]) -> None:
        ...


class DevProp():
    def __init__(self, prop_dict: dict):
        self.name = prop_dict["name"]
        self.desc = prop_dict["description"]
        self.type = prop_dict["type"]
        if self.type not in ["bool", "int", "uint", "float", "string"]:
            raise ValueError(f"不支持的类型: {self.type}, 可选类型: bool, int, uint, float, string")
        self.rw = prop_dict["rw"]
        self.range = prop_dict["range"]
        self.value_list = prop_dict.get("value-list", None)
        self.method = prop_dict["method"]

    def __str__(self):
        lines = [
            f"  {self.name}: {self.desc}",
            f"    valuetype: {self.type}, rw: {self.rw}, range: {self.range}"
        ]

        if self.value_list:
            value_lines = [f"    {item['value']}: {item['description']}" for item in self.value_list]
            lines.extend(value_lines)

        return "\n".join(lines)


class DevAction():
    def __init__(self, act_dict: dict):
        self.name = act_dict["name"]
        self.desc = act_dict["description"]
        self.method = act_dict["method"]
        self.arguments = act_dict.get("arguments", [])

    def __str__(self):
        return f"  {self.name}: {self.desc}"


class mijiaDevice():
    def __init__(
            self,
            api: mijiaAPI,
            did: Optional[str] = None,
            dev_name: Optional[str] = None,
            device_meta: Optional[dict[str, Any]] = None,
            device_info: Optional[dict[str, Any]] = None,
            sleep_time: float = 0.5,
    ):
        self.api = api

        if did is None and dev_name is None and device_meta is None:
            raise ValueError("必须提供 did 或 dev_name 参数之一")
        if did is not None and dev_name is not None:
            logger.warning("同时提供了 did 和 dev_name 参数，将忽略 dev_name")
        if device_meta is not None:
            did = did or device_meta.get("did")
            if did is None:
                raise ValueError("device_meta 缺少 did")
            dev_name = device_meta.get("name", dev_name)
            model = device_meta.get("model")
            if not model:
                raise ValueError("device_meta 缺少 model")
        else:
            devices_list = self.api.get_devices_list()
            if did is None:
                matches = [device for device in devices_list if device["name"] == dev_name]
                if not matches:
                    raise DeviceNotFoundError(dev_name)
                else:
                    if len(matches) > 1:
                        raise MultipleDevicesFoundError(f"找到多个 dev_name 为 '{dev_name}' 的设备，请使用 did 参数指定具体设备或者修改设备名称以区分")
                    did = matches[0]["did"]
                    model = matches[0]["model"]
            else:
                matches = [device for device in devices_list if device["did"] == did]
                if not matches:
                    raise DeviceNotFoundError(did)
                else:
                    if len(matches) > 1:
                        raise MultipleDevicesFoundError(f"找到多个 did 为 '{did}' 的设备，未预想的问题，欢迎提交 issue: https://github.com/Do1e/mijia-api/issues")
                    dev_name = matches[0].get("name", None)
                    model = matches[0]["model"]

        dev_info = device_info or get_device_info(
            model,
            cache_path=api.auth_data_path.parent,
            cache_backend=getattr(api, "device_spec_cache", None),
        )
        self.did = did
        self.model = model
        self.name = dev_name if dev_name is not None else dev_info["name"]
        self.sleep_time = sleep_time

        self.prop_list = {}
        for prop in dev_info.get("properties", []):
            prop_obj = DevProp(prop)
            name = prop["name"]
            self.prop_list[name] = prop_obj
            if "-" in name:
                self.prop_list[name.replace("-", "_")] = prop_obj

        self.action_list = {
            act["name"]: DevAction(act)
            for act in dev_info.get("actions", [])
        }

    def __str__(self) -> str:
        prop_list_str = "\n".join(filter(None, (str(v) for k, v in self.prop_list.items() if "_" not in k)))
        action_list_str = "\n".join(map(str, self.action_list.values()))
        return (f"{self.name} ({self.model})\n"
                f"Properties:\n{prop_list_str if prop_list_str else 'No properties available'}\n"
                f"Actions:\n{action_list_str if action_list_str else 'No actions available'}")


    def get(self, name: str) -> Union[bool, int, float, str]:
        if name not in self.prop_list:
            raise ValueError(f"不支持的属性: {name}, 可用属性: {list(self.prop_list.keys())}")
        prop = self.prop_list[name]
        if "r" not in prop.rw:
            raise ValueError(f"属性 {name} 不可读取")
        method = prop.method.copy()
        method["did"] = self.did
        result = self.api.get_devices_prop(method)
        if result["code"] != 0:
            raise DeviceGetError(self.name, name, result["code"])
        time.sleep(self.sleep_time)
        logger.debug(f"获取属性: {self.name} -> {name}, 结果: {result}")
        return result["value"]

    def set(self, name: str, value: Union[bool, int, float, str]) -> dict[str, Any]:
        if name not in self.prop_list:
            raise ValueError(f"不支持的属性: {name}, 可用属性: {list(self.prop_list.keys())}")
        prop = self.prop_list[name]
        if "w" not in prop.rw:
            raise ValueError(f"属性 {name} 不可写入")
        if prop.type == "bool":
            if isinstance(value, str):
                if value.lower() == "true":
                    value = True
                elif value.lower() == "false":
                    value = False
                elif value in ["0", "1"]:
                    value = bool(int(value))
                else:
                    raise ValueError(f"无效布尔值: {value}")
            elif isinstance(value, int):
                if value == 0:
                    value = False
                elif value == 1:
                    value = True
                else:
                    raise ValueError(f"无效布尔值: {value}")
            elif not isinstance(value, bool):
                raise ValueError(f"无效布尔值: {value}")
        elif prop.type in ["int", "uint"]:
            value = int(value)
            if prop.range:
                if value < prop.range[0] or value > prop.range[1]:
                    raise ValueError(f"{value} 超出数值范围, 应该在 {prop.range[:2]} 之间")
                if len(prop.range) >= 3 and prop.range[2] != 1:
                    if (value - prop.range[0]) % prop.range[2] != 0:
                        raise ValueError(
                            f"无效的值: {value}, 应该在范围 {prop.range[:2]} 内且步长为 {prop.range[2]}")
        elif prop.type == "float":
            value = float(value)
            if prop.range:
                if value < prop.range[0] or value > prop.range[1]:
                    raise ValueError(f"{value} 超出数值范围, 应该在 {prop.range[:2]} 之间")
                if len(prop.range) >= 3 and isinstance(prop.range[2], int):
                    if int(value - prop.range[0]) % prop.range[2] != 0:
                        raise ValueError(
                            f"无效的值: {value}, 应该在范围 {prop.range[:2]} 内且步长为 {prop.range[2]}")
        elif prop.type == "string":
            if not isinstance(value, str):
                raise ValueError(f"无效字符串值: {value}")
            if len(value.encode("utf-8")) > 192:
                raise ValueError(f"字符串值过长（最大 192 字节）")
        else:
            raise ValueError(f"不支持的类型: {prop.type}, 可用类型: bool, int, uint, float, string")
        if prop.value_list:
            if value not in [item["value"] for item in prop.value_list]:
                raise ValueError(f"无效值: {value}, 请使用 {prop.value_list}")
        method = prop.method.copy()
        method["did"] = self.did
        method["value"] = value
        result = self.api.set_devices_prop(method)
        if result["code"] == 1:
            logger.warning(f"网关已经接收指令，无法判断是否设置成功: {self.name} -> {name}, 值: {value}")
        elif result["code"] != 0:
            raise DeviceSetError(self.name, name, result["code"])
        time.sleep(self.sleep_time)
        logger.debug(f"设置属性: {self.name} -> {name}, 值: {value}, 结果: {result}")
        return result

    def __getattr__(self, name: str) -> Union[bool, int, float, str]:
        if "prop_list" in self.__dict__ and name in self.prop_list:
            return self.get(name)
        else:
            return super().__getattr__(name)

    def __setattr__(self, name: str, value: Union[bool, int, float, str]) -> None:
        if "prop_list" in self.__dict__ and name in self.prop_list:
            self.set(name, value)
        else:
            super().__setattr__(name, value)

    def run_action(
            self,
            name: str,
            value: Optional[Union[list, tuple]] = None,
            **kwargs
    ) -> dict[str, Any]:
        if name not in self.action_list:
            raise ValueError(f"不支持的动作: {name}, 可用动作: {list(self.action_list.keys())}")
        act = self.action_list[name]
        method = act.method.copy()
        method["did"] = self.did
        if value is not None:
            method["value"] = value
        if kwargs:
            for k, v in kwargs.items():
                if k.startswith("_"):
                    k = k[1:]
                if k in method:
                    raise ValueError(f"无效的参数: {k}. 请勿使用以下参数 ({', '.join(method.keys())})")
                method[k] = v
        result = self.api.run_action(method)
        if result["code"] == 1:
            logger.warning(f"网关已经接收指令，无法判断是否执行成功: {self.name} -> {name}")
        elif result["code"] != 0:
            raise DeviceActionError(self.name, name, result["code"])
        time.sleep(self.sleep_time)
        logger.debug(f"执行动作: {self.name} -> {name}, 结果: {result}")
        return result


def get_device_info(
    device_model: str,
    cache_path: Optional[Union[str, Path]] = None,
    cache_backend: Optional[DeviceInfoCacheBackend] = None,
) -> dict:
    """
    获取设备规格信息

    根据设备型号获取设备的详细规格信息，包括属性、操作等。
    支持缓存功能，避免重复请求网络。

    参数:
        device_model (str): 设备型号，例如 'yeelink.light.lamp4'
        cache_path (Optional[Union[str, Path]]): 可选，缓存目录路径。
            - 如果为 None，则不使用缓存
            - 如果指定，则将设备信息缓存到该目录下的 {device_model}.json 文件中
        cache_backend (Optional[DeviceInfoCacheBackend]): 可选，自定义缓存后端。
            - 如果提供，则优先使用该后端

    返回值:
        dict: 设备规格信息字典，包含以下字段：
            - name (str): 设备名称
            - model (str): 设备型号
            - properties (list): 设备属性列表，每个属性包含以下字段：
                - name (str): 属性名称
                - description (str): 属性描述
                - type (str): 属性数据类型（int、uint、float、bool、string）
                - rw (str): 读写权限（'r' 可读，'w' 可写，'rw' 可读写）
                - range (list): 属性值范围 [min, max, step]
                - value-list (list): 枚举值列表
                - method (dict): API 调用方法参数
            - actions (list): 设备操作/方法列表，每个操作包含以下字段：
                - name (str): 操作名称
                - description (str): 操作描述
                - method (dict): API 调用方法参数

    异常:
        GetDeviceInfoError: 当获取设备信息失败时抛出

    示例:
        >>> info = get_device_info('yeelink.light.lamp4')
        >>> print(info['name'])  # 输出设备名称
        >>> print(info['properties'][0]['name'])  # 输出第一个属性的名称
    """
    if cache_backend is not None:
        cached = cache_backend.get(device_model)
        if cached is not None and all(
            "notifiable" in prop and "unit" in prop
            for prop in cached.get("properties", [])
        ) and all(
            "arguments" in action and all(
                "description" in argument and "value-list" in argument
                for argument in action.get("arguments", [])
            )
            for action in cached.get("actions", [])
        ):
            return cached
    elif cache_path is not None:
        cache_file = Path(cache_path) / f"{device_model}.json"
        if cache_file.exists():
            logger.debug(f"从缓存加载设备信息: {cache_file}")
            with cache_file.open("r", encoding="utf-8") as f:
                cached = json.load(f)
            if all(
                "notifiable" in prop and "unit" in prop
                for prop in cached.get("properties", [])
            ) and all(
                "arguments" in action and all(
                    "description" in argument and "value-list" in argument
                    for argument in action.get("arguments", [])
                )
                for action in cached.get("actions", [])
            ):
                return cached
    timeout = float(os.getenv("MIJIA_REQUEST_TIMEOUT", "10"))
    retries = int(os.getenv("MIJIA_REQUEST_RETRIES", "2"))
    retry_delay = float(os.getenv("MIJIA_REQUEST_RETRY_DELAY", "0.5"))
    response = None
    last_error = None
    for attempt in range(retries + 1):
        try:
            response = requests.get(
                device_url + device_model,
                headers={"User-Agent": f"mijiaAPI/{version}"},
                timeout=timeout,
            )
            break
        except requests.exceptions.Timeout as exc:
            last_error = exc
            logger.warning("获取设备规格超时，第 %s 次重试", attempt + 1)
            if attempt >= retries:
                raise GetDeviceInfoError(device_model) from exc
        except requests.exceptions.RequestException as exc:
            last_error = exc
            logger.warning("获取设备规格失败，第 %s 次重试: %s", attempt + 1, exc)
            if attempt >= retries:
                raise GetDeviceInfoError(device_model) from exc
        time.sleep(retry_delay)
    if response is None or response.status_code != 200:
        raise GetDeviceInfoError(device_model) from last_error
    content = re.search(r"<script data-page=\"app\" type=\"application/json\">(.*?)</script>", response.text)
    if content is None:
        raise GetDeviceInfoError(device_model)
    content = content.group(1)
    content = json.loads(content)

    product = content["props"]["product"]
    name = product["name"]
    model = product["model"]
    i18n_zh = content["props"].get("i18n", {}).get("zh_cn", {})
    result = {
        "name": name,
        "model": model,
        "properties": [],
        "actions": []
    }
    services = content["props"]["tree"]["services"]

    properties_name = []
    actions_name = []
    for svc in services:
        siid = svc["iid"]
        svc_type = svc["type"]
        for prop in svc.get("properties", []):
            piid = prop["iid"]
            if prop["format"].startswith("int"):
                prop_type = "int"
            elif prop["format"].startswith("uint"):
                prop_type = "uint"
            else:
                prop_type = prop["format"]
            access_str = "".join([
                "r" if "read" in prop["access"] else "",
                "w" if "write" in prop["access"] else ""
            ])
            zh_cn = i18n_zh.get(f"service:{siid:03d}:property:{piid:03d}", "")
            item = {
                "name": prop["type"],
                "description": f"{prop['description']} / {zh_cn}".rstrip(" / "),
                "type": prop_type,
                "rw": access_str,
                "notifiable": "notify" in prop["access"],
                "unit": prop.get("unit", ""),
                "range": prop.get("valueRange", None),
                "value-list": None,
                "method": {
                    "siid": siid,
                    "piid": piid
                }
            }
            if prop.get("valueList"):
                item["value-list"] = []
                for vl_item in prop["valueList"]:
                    vl_zh = i18n_zh.get(vl_item.get("i18nKey", ""), "")
                    vl_entry = {
                        "value": vl_item["value"],
                        "description": vl_item["description"]
                    }
                    if vl_zh:
                        vl_entry["desc_zh_cn"] = vl_zh
                    item["value-list"].append(vl_entry)
            if item["name"] in properties_name:
                item["name"] = f"{svc_type}-{item['name']}"
            properties_name.append(item["name"])
            result["properties"].append(item)
        for act in svc.get("actions", []):
            aiid = act["iid"]
            zh_cn = i18n_zh.get(f"service:{siid:03d}:action:{aiid:03d}", "")
            act_item = {
                "name": act["type"],
                "description": f"{act['description']} / {zh_cn}".rstrip(" / "),
                "method": {
                    "siid": siid,
                    "aiid": aiid
                },
                "arguments": []
            }
            properties_by_iid = {
                prop["iid"]: prop for prop in svc.get("properties", [])
            }
            for piid in act.get("in", []):
                input_prop = properties_by_iid.get(piid, {})
                input_zh = i18n_zh.get(
                    f"service:{siid:03d}:property:{piid:03d}", ""
                )
                value_list = []
                for value_item in input_prop.get("valueList", []):
                    value_zh = i18n_zh.get(value_item.get("i18nKey", ""), "")
                    value_entry = {
                        "value": value_item["value"],
                        "description": value_item["description"],
                    }
                    if value_zh:
                        value_entry["desc_zh_cn"] = value_zh
                    value_list.append(value_entry)
                act_item["arguments"].append({
                    "piid": piid,
                    "name": input_prop.get("type", ""),
                    "description": (
                        f"{input_prop.get('description', '')} / {input_zh}"
                    ).rstrip(" / "),
                    "type": input_prop.get("format", ""),
                    "unit": input_prop.get("unit", ""),
                    "range": input_prop.get("valueRange"),
                    "value-list": value_list or None,
                    "required": True,
                })
            if act_item["name"] in actions_name:
                act_item["name"] = f"{svc_type}-{act_item['name']}"
            actions_name.append(act_item["name"])
            result["actions"].append(act_item)

    if cache_backend is not None:
        cache_backend.set(device_model, result)
    elif cache_path is not None:
        cache_path = Path(cache_path)
        cache_path.mkdir(parents=True, exist_ok=True)
        cache_file = cache_path / f"{device_model}.json"
        logger.debug(f"缓存设备信息到: {cache_file}")
        with cache_file.open("w", encoding="utf-8") as f:
            json.dump(result, f, indent=2, ensure_ascii=False)
    return result

"""Privacy-preserving desktop validation for D13x proactive intelligence."""

from __future__ import annotations

import argparse
import json
import os
import re
import subprocess
from collections import Counter, defaultdict
from pathlib import Path
from typing import Any

import requests

from .api_server import (
    AgentCloudAdvisor,
    _load_agent_skill,
    _load_private_agent_environment,
)


SAFE_AUTOMATION_CATEGORIES = {"light", "switch", "outlet"}
SENSITIVE_CATEGORIES = {
    "camera",
    "door-lock",
    "gas-sensor",
    "gas-valve",
    "smoke-sensor",
}
SENSOR_CATEGORY_SUFFIXES = ("sensor", "meter")


def _run_miloco(*arguments: str) -> str:
    completed = subprocess.run(
        ["miloco-cli", *arguments],
        check=True,
        capture_output=True,
        text=True,
        timeout=20,
    )
    return completed.stdout


def parse_device_list(text: str) -> list[dict[str, Any]]:
    devices: list[dict[str, Any]] = []
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        fields = line.split("|")
        if len(fields) != 5 or fields[4] not in {"online", "offline"}:
            continue
        devices.append(
            {
                "did": fields[0],
                "name": fields[1],
                "room": fields[2],
                "category": fields[3],
                "online": fields[4] == "online",
            }
        )
    return devices


def parse_catalog_specs(text: str) -> dict[str, list[dict[str, str]]]:
    specs: dict[str, list[dict[str, str]]] = defaultdict(list)
    current_devices: list[str] = []
    in_specs = False
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if line == "---":
            in_specs = True
            continue
        fields = line.split("|")
        if len(fields) == 5 and fields[4] in {"online", "offline"}:
            if in_specs:
                current_devices = []
            current_devices.append(fields[0])
            in_specs = False
            continue
        if in_specs and current_devices and len(fields) >= 2 and fields[1] in {
            "r",
            "w",
            "wr",
            "x",
        }:
            for did in current_devices:
                specs[did].append(
                    {
                        "name": fields[0],
                        "access": fields[1],
                        "format": fields[2] if len(fields) > 2 else "",
                    }
                )
    return dict(specs)


def build_anonymous_inventory(
    devices: list[dict[str, Any]],
    specs: dict[str, list[dict[str, str]]],
) -> dict[str, Any]:
    room_aliases: dict[str, str] = {}
    category_total: Counter[str] = Counter()
    category_online: Counter[str] = Counter()
    room_categories: dict[str, Counter[str]] = defaultdict(Counter)
    writable_boolean = 0
    writable_numeric = 0
    readable_sensor = 0
    actions = 0
    safe_targets = 0
    observable_triggers = 0
    sensitive_devices = 0

    for device in devices:
        room = str(device["room"])
        alias = room_aliases.setdefault(
            room, f"room_{len(room_aliases) + 1}"
        )
        category = str(device["category"])
        category_total[category] += 1
        room_categories[alias][category] += 1
        if device["online"]:
            category_online[category] += 1
        if category in SENSITIVE_CATEGORIES:
            sensitive_devices += 1

        device_specs = specs.get(str(device["did"]), [])
        has_safe_writable = False
        has_readable_signal = False
        for spec in device_specs:
            access = spec["access"]
            value_format = spec["format"].split("|", 1)[0]
            if "w" in access:
                if value_format == "bool":
                    writable_boolean += 1
                else:
                    writable_numeric += 1
                has_safe_writable = True
            if "r" in access and "w" not in access:
                readable_sensor += 1
                has_readable_signal = True
            if access == "x":
                actions += 1

        if (
            device["online"]
            and category in SAFE_AUTOMATION_CATEGORIES
            and has_safe_writable
        ):
            safe_targets += 1
        if (
            device["online"]
            and (
                category.endswith(SENSOR_CATEGORY_SUFFIXES)
                or has_readable_signal
            )
        ):
            observable_triggers += 1

    categories = [
        {
            "category": category,
            "total": category_total[category],
            "online": category_online[category],
        }
        for category in sorted(category_total)
    ]
    rooms = [
        {
            "room": alias,
            "device_count": sum(values.values()),
            "categories": dict(sorted(values.items())),
        }
        for alias, values in sorted(room_categories.items())
    ]
    return {
        "schema": "d13x.proactive.inventory.v1",
        "device_count": len(devices),
        "online_count": sum(bool(device["online"]) for device in devices),
        "room_count": len(room_aliases),
        "categories": categories,
        "capabilities": {
            "writable_boolean": writable_boolean,
            "writable_numeric": writable_numeric,
            "readable_sensor": readable_sensor,
            "actions": actions,
            "safe_automation_targets": safe_targets,
            "observable_triggers": observable_triggers,
        },
        "candidate_families": [
            {
                "kind": "time_routine",
                "eligible_targets": safe_targets,
                "minimum_distinct_days": 5,
                "local_confidence_threshold": 65,
            },
            {
                "kind": "event_routine",
                "observable_triggers": observable_triggers,
                "eligible_targets": safe_targets,
                "minimum_observations": 3,
                "local_confidence_threshold": 65,
            },
        ],
        "safety": {
            "excluded_sensitive_devices": sensitive_devices,
            "requires_user_confirmation": True,
            "cloud_can_create_device_commands": False,
        },
        "rooms": rooms,
    }


def _normalize_cloud_review(value: dict[str, Any]) -> dict[str, Any]:
    readiness = value.get("readiness")
    if readiness not in {"ready", "limited"}:
        readiness = "limited"
    focus = value.get("recommended_focus")
    if not isinstance(focus, list):
        focus = []
    allowed_focus = {
        "time_routine",
        "event_routine",
        "environment_guard",
    }
    focus = [item for item in focus[:3] if item in allowed_focus]
    risks = value.get("risks")
    if not isinstance(risks, list):
        risks = []
    risks = [
        re.sub(r"\s+", " ", item).strip()[:80]
        for item in risks[:4]
        if isinstance(item, str) and item.strip()
    ]
    try:
        minimum_evidence = int(value.get("minimum_evidence", 5))
    except (TypeError, ValueError):
        minimum_evidence = 5
    try:
        confidence_threshold = int(value.get("confidence_threshold", 65))
    except (TypeError, ValueError):
        confidence_threshold = 65
    return {
        "readiness": readiness,
        "recommended_focus": focus,
        "minimum_evidence": max(3, min(30, minimum_evidence)),
        "confidence_threshold": max(65, min(95, confidence_threshold)),
        "risks": risks,
        "device_commands_created": False,
    }


def cloud_review_inventory(
    inventory: dict[str, Any],
    *,
    state_dir: Path,
) -> dict[str, Any]:
    _load_private_agent_environment(state_dir)
    advisor = AgentCloudAdvisor(skill_name="d13x-server-ai")
    if not advisor.configured:
        return _normalize_cloud_review(
            {
                "readiness": "limited",
                "recommended_focus": ["time_routine", "event_routine"],
                "risks": ["云端模型未配置，本次仅完成本地分析"],
            }
        )

    server_skill = _load_agent_skill("d13x-server-ai")
    prompt = (
        f"{server_skill}\n\n"
        "你将收到本地算法生成的匿名设备能力清单。只评估该家庭是否具备"
        "持续学习条件，不得推断真实设备名称、房间、住址或账号，不得生成"
        "设备命令。输出严格 JSON：readiness=ready/limited；"
        "recommended_focus 仅可包含 time_routine/event_routine/"
        "environment_guard；minimum_evidence 为 3..30；"
        "confidence_threshold 为 65..95；risks 最多 4 条。"
    )
    response = requests.post(
        advisor._endpoint,
        headers={
            "Authorization": f"Bearer {advisor._api_key}",
            "Content-Type": "application/json",
        },
        json={
            "model": advisor._model,
            "temperature": 0.1,
            "messages": [
                {"role": "system", "content": prompt},
                {
                    "role": "user",
                    "content": json.dumps(
                        inventory, ensure_ascii=False, sort_keys=True
                    ),
                },
            ],
        },
        timeout=advisor._timeout,
    )
    response.raise_for_status()
    data = response.json()
    result = AgentCloudAdvisor._extract_json(
        data["choices"][0]["message"]["content"]
    )
    return _normalize_cloud_review(result)


def collect_inventory() -> dict[str, Any]:
    devices = parse_device_list(_run_miloco("device", "list"))
    specs = parse_catalog_specs(_run_miloco("device", "catalog"))
    return build_anonymous_inventory(devices, specs)


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Run the D13x local inventory algorithm safely."
    )
    parser.add_argument(
        "--cloud",
        action="store_true",
        help="Send only the anonymous aggregate to the cloud advisor.",
