def _extract_sync_state(snapshot: dict[str, Any]) -> dict[str, Any]:
    structure = {
        "homes": sorted([
            {
                "id": home["id"],
                "name": home["name"],
                "rooms": sorted([
                    {
                        "id": room["id"],
                        "name": room["name"],
                        "dids": sorted(room["dids"]),
                    }
                    for room in home["rooms"]
                ], key=lambda room: room["id"]),
            }
            for home in snapshot["homes"]
        ], key=lambda home: home["id"]),
        "devices": sorted([
            {
                "did": device["did"],
                "name": device["name"],
                "model": device["model"],
                "home_id": device["home_id"],
                "room_id": device["room_id"],
                "room_name": device["room_name"],
                "device_type": device["device_type"],
                "detail_available": device["detail_available"],
                "properties": sorted([
                    {
                        "name": prop["name"],
                        "display_name": prop.get("display_name", prop["name"]),
                        "siid": prop["siid"],
                        "piid": prop["piid"],
                        "type": prop.get("type", ""),
                        "unit": prop.get("unit", ""),
                        "rw": prop["rw"],
                        "range": prop["range"],
                        "range_scaled": prop.get("range_scaled"),
                        "value_scale": prop.get("value_scale", 1),
                        "value_list": prop.get("value_list"),
                        "ui_options": prop.get("ui_options", []),
                        "ui_control": prop.get("ui_control", "none"),
                    }
                    for prop in device["properties"]
                ], key=lambda prop: (prop["siid"], prop["piid"])),
                "actions": sorted([
                    {
                        "name": action["name"],
                        "display_name": action.get(
                            "display_name", action["name"]
                        ),
                        "siid": action["siid"],
                        "aiid": action["aiid"],
                        "executable": bool(action.get("executable", False)),
                        "argument_count": len(action.get("arguments", [])),
                        "argument_hint": action.get("argument_hint", ""),
                        "arguments": action.get("arguments", []),
                    }
                    for action in device.get("actions", [])
                ], key=lambda action: (action["siid"], action["aiid"])),
            }
            for device in snapshot["devices"]
        ], key=lambda device: device["did"]),
        "scenes": sorted([
            {
                "scene_id": scene["scene_id"],
                "name": scene["name"],
                "home_id": scene["home_id"],
            }
            for scene in snapshot["scenes"]
        ], key=lambda scene: scene["scene_id"]),
    }
    devices = {}
    for device in snapshot["devices"]:
        properties = {}
        for prop in device["properties"]:
            # The cloud readback path also observes readable properties that
            # are not marked notify in some older product specifications.
            # They use the same MIoT delta envelope for the panel transport.
            if not prop.get("readable", False):
                continue
            key = f"{prop['siid']}:{prop['piid']}"
            properties[key] = {
                "siid": prop["siid"],
                "piid": prop["piid"],
                "value": _normalize_sync_value(prop.get("current_value")),
                "value_scaled": prop.get("current_value_scaled"),
                "value_scale": prop.get("value_scale", 1),
                "display_value": prop.get("display_value", "--"),
                "error": _normalize_sync_value(prop.get("current_error")),
            }
        devices[device["did"]] = {
            "online": device["isOnline"],
            "properties": properties,
        }
    return {
        "structure": json.dumps(structure, ensure_ascii=False, sort_keys=True, separators=(",", ":")),
        "devices": devices,
    }


def _build_panel_sync_snapshot(
    snapshot: dict[str, Any], revision: int
) -> dict[str, Any]:
    """Return the compact MIoT view consumed by the embedded panel.

    The server keeps the complete device specifications for command validation
    and delta generation.  Sending descriptions, raw value lists and action
    argument schemas again in every full sync roughly doubles the cJSON heap
    required by the D13x without adding anything to its dynamic controls.
    """

    device_fields = (
        "did",
        "name",
        "room_name",
        "model",
        "device_type",
        "isOnline",
    )
    property_fields = (
        "name",
        "display_name",
        "display_value",
        "siid",
        "piid",
        "type",
        "current_value",
        "current_value_scaled",
        "rw",
        "range",
        "range_scaled",
        "value_scale",
        "ui_control",
        "ui_options",
        "unit_label",
    )
    action_fields = (
        "name",
        "display_name",
        "argument_hint",
        "argument_count",
        "siid",
        "aiid",
    )

    devices = []
    for source in snapshot.get("devices", []):
        device = {key: source.get(key) for key in device_fields}
        device["properties"] = [
            {key: prop.get(key) for key in property_fields if key in prop}
            for prop in source.get("properties", [])
        ]
        device["actions"] = [
            {key: action.get(key) for key in action_fields if key in action}
            for action in source.get("actions", [])
        ]
        devices.append(device)

    return {
        "generated_at": snapshot.get("generated_at", int(time.time())),
        "protocol": snapshot.get("protocol", {}),
        "summary": snapshot.get("summary", {}),
        "homes": snapshot.get("homes", []),
        "devices": devices,
        "scenes": snapshot.get("scenes", []),
        "sync_revision": revision,
    }


def _normalize_sync_value(value: Any) -> Any:
    """Make cloud values deterministic before comparing sync revisions."""

    if isinstance(value, float) and not math.isfinite(value):
        return None
    if isinstance(value, dict):
        return {
            str(key): _normalize_sync_value(item)
            for key, item in sorted(value.items(), key=lambda pair: str(pair[0]))
        }
    if isinstance(value, (list, tuple)):
        return [_normalize_sync_value(item) for item in value]
    return value


def _build_sync_delta(
    previous: dict[str, Any],
    current: dict[str, Any],
) -> tuple[list[dict[str, Any]], bool]:
    if previous["structure"] != current["structure"]:
        return [], True

    previous_devices = previous["devices"]
    current_devices = current["devices"]
    if previous_devices.keys() != current_devices.keys():
        return [], True

    online_changes = []
    property_changes = []
    for did, device in current_devices.items():
        old_device = previous_devices[did]
        if old_device["online"] != device["online"]:
            online_changes.append({
                "did": did,
                "previous_value": old_device["online"],
                "value": device["online"],
            })

        old_properties = old_device["properties"]
        properties = device["properties"]
        if old_properties.keys() != properties.keys():
            return [], True
        for key, prop in properties.items():
            old_prop = old_properties[key]
            if old_prop["value"] == prop["value"] and old_prop["error"] == prop["error"]:
                continue
            property_changes.append({
                "did": did,
                "siid": prop["siid"],
                "piid": prop["piid"],
                "previous_value": old_prop["value"],
                "previous_code": 0 if old_prop["error"] is None else -1,
                "value": prop["value"],
                "value_scaled": prop.get("value_scaled"),
                "value_scale": prop.get("value_scale", 1),
                "display_value": prop.get("display_value", "--"),
                "code": 0 if prop["error"] is None else -1,
            })

    changes = []
    if online_changes:
        changes.append({"method": "device_online_changed", "params": online_changes})
    if property_changes:
        changes.append({"method": "properties_changed", "params": property_changes})
    return changes, False


