@app.post("/api/agent/proposal/confirm")
def confirm_agent_board_proposal(
    payload: AgentProposalConfirmPayload,
    session: ManagedSession = Depends(enforce_agent_rate_limit),
    _: None = Depends(request_slot),
):
    proposal = session.board_proposal_record(payload.proposal_id)
    if proposal.get("kind") != "automation":
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail="一次性建议无需服务端二次生成，可由板端确认后直接执行",
        )
    if proposal.get("status") not in {
        "awaiting_confirmation", "generating_plan",
    }:
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail="该自动化建议已处理",
        )
    if int(proposal.get("expires_at", 0)) <= int(time.time()):
        raise HTTPException(
            status_code=status.HTTP_410_GONE,
            detail="该自动化建议已过期",
        )
    context = session.board_analysis_context()
    session.update_board_proposal(
        payload.proposal_id,
        status_value="generating_plan",
        feedback="accepted",
    )
    material = {
        "request_purpose": payload.purpose,
        "consented_purpose": proposal["purpose"],
        "consented_explanation": proposal["explanation"],
        "consented_trigger": proposal["trigger"],
        "consented_intents": proposal["intents"],
    }
    try:
        raw_plan = server_agent_advisor.generate_confirmed_automation(
            material
        )
        plan = _agent_normalize_confirmed_plan(
            raw_plan,
            proposal,
            context["latest_state"],
        )
    except (KeyError, TypeError, ValueError, RuntimeError,
            requests.RequestException):
        session.update_board_proposal(
            payload.proposal_id,
            status_value="awaiting_confirmation",
        )
        raise HTTPException(
            status_code=status.HTTP_502_BAD_GATEWAY,
            detail=_public_error_payload(
                "自动化计划生成或安全校验失败，请稍后重试",
                "agent_plan_generation_failed",
            ),
        )
    updated = session.update_board_proposal(
        payload.proposal_id,
        status_value="plan_ready",
        plan=plan,
    )
    return {
        "ok": True,
        "request_purpose": payload.purpose,
        "response_purpose": (
            "返回用户已同意且通过能力白名单校验的自动化 JSON，"
            "供板端执行并离线保存"
        ),
        "proposal": updated,
        "plan": plan,
    }

