    for prop in info.get("properties", []):
        if "r" in prop.get("rw", ""):
            method = prop["method"].copy()
            method["did"] = did
            readable_params.append(method)
            prop_key_mapping[(prop["method"]["siid"], prop["method"]["piid"])] = prop["name"]

    values_map: dict[str, Any] = {}

    loaded = False
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#") or "=" not in stripped:
            continue
        key, value = stripped.split("=", 1)
        key = key.strip()
        if key not in AGENT_ENV_KEYS or key in os.environ:
            continue
        value = value.strip()
        if ((value.startswith('"') and value.endswith('"')) or
                (value.startswith("'") and value.endswith("'"))):
            value = value[1:-1]
        if "\x00" in value or "\n" in value or "\r" in value:
            continue
        os.environ[key] = value
        loaded = True
    return loaded


def _bounded_agent_text(value: Any, limit: int) -> str:
    if not isinstance(value, str):
        return ""
    value = re.sub(r"[\x00-\x1f\x7f]", " ", value)
    value = re.sub(r"\s+", " ", value).strip()
    encoded = value.encode("utf-8")
    if len(encoded) <= limit:
        return value
    return encoded[:limit].decode("utf-8", errors="ignore")


def _load_agent_skill(name: str, *, limit: int = 12 * 1024) -> str:
    """Load a repository-owned Skill without following external links."""

    if not re.fullmatch(r"[a-z0-9-]+", name):
        return ""
    path = AGENT_SKILL_ROOT / name / "SKILL.md"
    try:
        if path.is_symlink() or not path.is_file():
            return ""
        raw = path.read_bytes()
    except OSError:
        return ""
    if len(raw) > limit:
        return ""
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        return ""
    if text.startswith("---\n"):
        marker = text.find("\n---\n", 4)
        if marker >= 0:
            text = text[marker + 5:]
    return text.strip()


