        session = ManagedSession.__new__(ManagedSession)
        session._sync_lock = threading.RLock()
        session._sync_revision = 4
        session._sync_state = _state(value=4)
        session._sync_events = deque([
            _event(3, 4, []),
        ], maxlen=SYNC_EVENT_HISTORY_LIMIT)
